// Owner business report: weekly (Mondays) and monthly (1st of the month).
const Z = 'Asia/Dubai';
const now = DateTime.now().setZone(Z);
function all(n) { try { return $(n).all().map(function (i) { return i.json || {}; }).filter(function (r) { return Object.keys(r).length && !r.error; }); } catch (e) { return []; } }
const trig = ($('Report Schedule').first() || {}).json || {};
const monthly = String(trig.Minute || '') === '17' || String(($('Report Schedule').first().json || {}).period || '') === 'month';
const start = monthly ? now.minus({ months: 1 }).startOf('month') : now.minus({ days: 7 }).startOf('day');
const end = monthly ? now.startOf('month') : now.startOf('day');
// switches: owner_report (weekly) and monthly_report (monthly)
const on = {};
all('Get Switches').forEach(function (r) { if (r.feature) on[String(r.feature).trim()] = String(r.enabled).trim().toUpperCase() === 'TRUE'; });
if (monthly ? !on.monthly_report : !on.owner_report) return [];
const inRange = function (t) { const d = DateTime.fromFormat(String(t || ''), 'yyyy-MM-dd HH:mm', { zone: Z }); return d.isValid && d >= start && d < end; };

// clinic setup
const c = {};
all('Get Setup').filter(function (r) { return r.tab === 'clinic'; }).forEach(function (r) { c[r.name] = String(r.value || '').trim(); });
const prices = all('Get Setup').filter(function (r) { return r.tab === 'price' && !isNaN(Number(r.value)); });
const clinic = c.clinic_name || 'BrightSmile Dental';
const cur = c.currency || 'AED';
const owner = String(c.owner_phone || '').replace(/\D/g, '') || '000000000000';
const DAYS = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday'];
const openAt = function (d) {
  const h = String(c['hours_' + DAYS[d.weekday - 1]] || (d.weekday === 5 ? '14:00-21:00' : '09:00-21:00'));
  const m = h.match(/(\d{1,2}):(\d{2})\s*-\s*(\d{1,2}):(\d{2})/);
  if (!m) return false;
  const mins = d.hour * 60 + d.minute;
  return mins >= Number(m[1]) * 60 + Number(m[2]) && mins < Number(m[3]) * 60 + Number(m[4]);
};
const isTest = function (p) { const s = String(p || '').replace(/\D/g, ''); return !s || /^000000000000/.test(s) || s === owner; };

// conversations
const conv = all('Read Conversations').filter(function (r) { return inRange(r.time) && !isTest(r.phone); });
const incoming = conv.filter(function (r) { return r.direction === 'in'; });
const replies = conv.filter(function (r) { return r.direction === 'out'; });
const afterHours = replies.filter(function (r) { return !openAt(DateTime.fromFormat(String(r.time), 'yyyy-MM-dd HH:mm', { zone: Z })); });
const people = {};
incoming.forEach(function (r) { people[String(r.phone).replace(/\D/g, '')] = true; });
const firstSeen = {};
all('Read Conversations').forEach(function (r) { const p = String(r.phone || '').replace(/\D/g, ''); if (r.direction === 'in' && p && !firstSeen[p]) firstSeen[p] = String(r.time); });
const newPeople = Object.keys(people).filter(function (p) { return inRange(firstSeen[p]); });

// bookings made by Noor (calendar events created in the period)
const events = all('Get Events').filter(function (e) { return e.id && e.status !== 'cancelled'; });
const made = events.filter(function (e) {
  const created = DateTime.fromISO(String(e.created || ''), { zone: Z });
  return created.isValid && created >= start && created < end && /Booked by Noor/i.test(String(e.description || '')) && !/000000000000/.test(String(e.description || ''));
});
const online = made.filter(function (e) { return /online booking page/i.test(String(e.description || '')); });
const valueOf = function (summary) {
  const s = String(summary || '').toLowerCase();
  const p = prices.find(function (r) { return String(r.words || '').toLowerCase().split(',').map(function (w) { return w.trim(); }).filter(Boolean).some(function (w) { return s.includes(w); }); });
  return p ? Number(p.value) : 0;
};
const value = made.reduce(function (sum, e) { return sum + valueOf(e.summary); }, 0);
const next7 = events.filter(function (e) { const s = DateTime.fromISO(String((e.start || {}).dateTime || ''), { zone: Z }); return s.isValid && s >= now && s < now.plus({ days: 7 }); });

// patients, requests, unanswered
const patients = all('Read Patients').filter(function (p) { return !isTest(p.phone); });
const waiting = patients.filter(function (p) { return String(p.status || '').toLowerCase() === 'human'; });
const leads = patients.filter(function (p) { return String(p.status || '').toLowerCase() === 'lead'; });
const reqs = all('Read Requests').filter(function (r) { return !isTest(r.phone); });
const reqNew = reqs.filter(function (r) { return inRange(r.time); });
const reqOpen = reqs.filter(function (r) { return ['ready', 'done', 'closed'].indexOf(String(r.status || '').toLowerCase().trim()) < 0; });
const unanswered = all('Read Unanswered').filter(function (r) { return inRange(r.time) && !isTest(r.phone); });

const label = monthly ? start.toFormat('LLLL yyyy') : start.toFormat('d LLL') + ' – ' + end.minus({ days: 1 }).toFormat('d LLL');
const lines = [
  '*' + clinic + ' – ' + (monthly ? 'monthly' : 'weekly') + ' report (' + label + ')*',
  '',
  '👥 Patients who messaged: *' + Object.keys(people).length + '* (' + newPeople.length + ' new)',
  '💬 Replies sent by Noor: *' + replies.length + '* (' + afterHours.length + ' outside opening hours)',
  '📅 Bookings made by Noor: *' + made.length + '*' + (online.length ? ' (' + online.length + ' from the website)' : '') + (value ? ', about ' + cur + ' ' + value.toLocaleString('en-US') : ''),
  '🗓️ Appointments in the next 7 days: *' + next7.length + '*',
  '📝 Requests: ' + reqNew.length + ' new, ' + reqOpen.length + ' still open',
  '🙋 Waiting for a person: ' + waiting.length + (waiting.length ? ' (' + waiting.slice(0, 3).map(function (p) { return p.name || ('+' + p.phone); }).join(', ') + ')' : ''),
  '🎯 Leads who have not booked yet: ' + leads.length,
  '❓ Questions Noor could not answer: ' + unanswered.length + (unanswered.length ? ' (see the Unanswered tab)' : '')
];
return [{ json: { owner: owner, text: lines.join('\n'), period: monthly ? 'month' : 'week' } }];

// Daily owner PDF report: builds the HTML from today's calendar, the Patients, Requests, Unanswered and Conversations tabs and the automatic-message log.
const Z = 'Asia/Dubai';
const now = DateTime.now().setZone(Z);
const today = now.startOf('day');
const yStart = today.minus({ days: 1 });
const weekStart = today.minus({ days: today.weekday - 1 });
function all(n) { try { return $(n).all().map(function (i) { return i.json || {}; }).filter(function (r) { return Object.keys(r).length && !r.error; }); } catch (e) { return []; } }
function esc(s) { return String(s == null ? '' : s).replace(/[&<>"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; }); }
const on = {};
all('Get Switches').forEach(function (r) { if (r.feature) on[String(r.feature).trim()] = String(r.enabled).trim().toUpperCase() === 'TRUE'; });
const forced = (function () { try { return $('Send PDF Now').isExecuted; } catch (e) { return false; } })();
if (!forced && on.daily_pdf_report === false) return [];
const c = {};
all('Get Setup').filter(function (r) { return r.tab === 'clinic'; }).forEach(function (r) { c[r.name] = String(r.value || '').trim(); });
const prices = all('Get Setup').filter(function (r) { return r.tab === 'price' && !isNaN(Number(r.value)); });
const clinic = c.clinic_name || 'BrightSmile Dental';
const cur = c.currency || 'AED';
const owner = String(c.owner_phone || '').replace(/\D/g, '') || '000000000000';
const digits = function (p) { return String(p || '').replace(/\D/g, ''); };
const isTest = function (p) { const s = digits(p); return !s || /^000000000000/.test(s) || s === owner; };
const t = function (s) { return DateTime.fromFormat(String(s || ''), 'yyyy-MM-dd HH:mm', { zone: Z }); };
const between = function (d, a, b) { return d.isValid && d >= a && d < b; };
const valueOf = function (summary) {
  const s = String(summary || '').toLowerCase();
  const p = prices.find(function (r) { return String(r.words || '').toLowerCase().split(',').map(function (w) { return w.trim(); }).filter(Boolean).some(function (w) { return s.includes(w); }); });
  return p ? Number(p.value) : 0;
};
const money = function (n) { return cur + ' ' + Math.round(n).toLocaleString('en-US'); };
const DAYS = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday'];
const openAt = function (d) {
  const h = String(c['hours_' + DAYS[d.weekday - 1]] || (d.weekday === 5 ? '14:00-21:00' : '09:00-21:00'));
  const m = h.match(/(\d{1,2}):(\d{2})\s*-\s*(\d{1,2}):(\d{2})/);
  if (!m) return false;
  const mins = d.hour * 60 + d.minute;
  return mins >= Number(m[1]) * 60 + Number(m[2]) && mins < Number(m[3]) * 60 + Number(m[4]);
};

// patients by phone
const patients = all('Read Patients');
const byPhone = {};
patients.forEach(function (p) { const d = digits(p.phone); if (d) byPhone[d] = p; });

// calendar
const events = all('Get Events').filter(function (e) { return e.id && e.status !== 'cancelled' && e.start && e.start.dateTime; });
const evStart = function (e) { return DateTime.fromISO(e.start.dateTime, { zone: Z }); };
const evPhone = function (e) { const m = String(e.description || '').match(/phone:\s*\+?(\d{8,15})/i); return m ? m[1] : ''; };
const todays = events.filter(function (e) { return between(evStart(e), today, today.plus({ days: 1 })) && !isTest(evPhone(e)); })
  .sort(function (a, b) { return evStart(a).toMillis() - evStart(b).toMillis(); });
const madeBy = function (e) { return /Booked by Noor/i.test(String(e.description || '')); };
const created = function (e) { return DateTime.fromISO(String(e.created || ''), { zone: Z }); };
const rows = todays.map(function (e) {
  const parts = String(e.summary || '').split(/\s+[–-]\s+/);
  const svc = parts[0] || 'Appointment';
  const name = parts.slice(1).join(' – ') || 'Patient';
  const dm = String(e.description || '').match(/Dentist:\s*([^.]+(?:\.[^.]+)?)\./);
  const dentist = dm ? dm[1].trim() : '';
  const p = byPhone[evPhone(e)] || {};
  const family = /family member/i.test(String(e.description || ''));
  const confirmed = !family && /confirmed/i.test(String(p.status || ''));
  const isNew = !family && /new|جديد/i.test(String(p.new_or_returning || ''));
  const web = /online booking page/i.test(String(e.description || ''));
  return { time: evStart(e).toFormat('HH:mm'), name: name, svc: svc, dentist: dentist, confirmed: confirmed, isNew: isNew, family: family, web: web, value: valueOf(e.summary) };
});
const todayValue = rows.reduce(function (s, r) { return s + r.value; }, 0);
const confirmedCount = rows.filter(function (r) { return r.confirmed; }).length;
const newToday = rows.filter(function (r) { return r.isNew; }).length;
const madeYesterday = events.concat(all('Get Events').filter(function (e) { return e.status === 'cancelled'; }))
  .filter(function (e) { return madeBy(e) && between(created(e), yStart, today) && !/000000000000/.test(String(e.description || '')); });
const webYesterday = madeYesterday.filter(function (e) { return /online booking page/i.test(String(e.description || '')); }).length;
const madeWeek = events.filter(function (e) { return madeBy(e) && between(created(e), weekStart, now) && !/000000000000/.test(String(e.description || '')); });
const madeLastWeek = events.filter(function (e) { return madeBy(e) && between(created(e), weekStart.minus({ days: 7 }), weekStart) && !/000000000000/.test(String(e.description || '')); });
const weekValue = madeWeek.reduce(function (s, e) { return s + valueOf(e.summary); }, 0);

// needs attention
const real = patients.filter(function (p) { return !isTest(p.phone); });
const waiting = real.filter(function (p) { return String(p.status || '').toLowerCase().trim() === 'human'; });
const unconfirmed = rows.filter(function (r) { return !r.confirmed && !r.family; });
const reqOpen = all('Read Requests').filter(function (r) { return !isTest(r.phone) && ['ready', 'done', 'closed'].indexOf(String(r.status || '').toLowerCase().trim()) < 0; });
const unanswered = all('Read Unanswered').filter(function (r) { return !isTest(r.phone) && between(t(r.time), yStart, today); });
const leads = real.filter(function (p) { return String(p.status || '').toLowerCase().trim() === 'lead'; });

// yesterday on WhatsApp
const conv = all('Read Conversations').filter(function (r) { return !isTest(r.phone) && between(t(r.time), yStart, today); });
const inMsgs = conv.filter(function (r) { return r.direction === 'in'; });
const outMsgs = conv.filter(function (r) { return r.direction === 'out'; });
const people = {};
inMsgs.forEach(function (r) { people[digits(r.phone)] = 1; });
const afterHours = outMsgs.filter(function (r) { return !openAt(t(r.time)); }).length;
const voice = inMsgs.filter(function (r) { return String(r.type || '') === 'audio'; }).length;

// automatic messages yesterday (sent log)
const sent = all('Get Sent Log').filter(function (r) { return between(t(r.sent_at), yStart, today) && !isTest(r.phone); });
const kind = function (k) { return sent.filter(function (r) { return k.indexOf(String(r.kind || '')) >= 0; }).length; };
const auto = [
  ['Reminders (3-day, 24h, 2h)', kind(['reminder', 'reminder3d', 'reminder_3d'])],
  ['Welcome and aftercare messages', kind(['tips', 'first_visit', 'aftercare'])],
  ['Follow-ups to people who didn’t book', kind(['followup', 'winback', 'win_back'])],
  ['Visit rating and review requests', kind(['feedback', 'review'])],
  ['Recall and no-show messages', kind(['recall', 'missed'])]
];

// HTML
const pill = function (cls, txt) { return '<span class="pill ' + cls + '">' + txt + '</span>'; };
const tableRows = rows.length ? rows.map(function (r) {
  return '<tr><td class="time">' + r.time + '</td><td>' + esc(r.name) + (r.isNew ? ' ' + pill('new', 'New') : '') + (r.family ? ' ' + pill('fam', 'Family') : '') + (r.web ? ' ' + pill('web', 'Website') : '') + '</td><td>' + esc(r.svc) + '</td><td>' + esc(r.dentist) + '</td><td>' + (r.confirmed ? pill('ok', 'Confirmed') : pill('wait', 'Not confirmed')) + '</td></tr>';
}).join('') : '<tr><td colspan="5" class="empty">No appointments in the calendar today.</td></tr>';
const att = [];
if (waiting.length) att.push('<li><b>' + waiting.length + ' patient' + (waiting.length > 1 ? 's are' : ' is') + ' waiting for a person</b>: ' + esc(waiting.slice(0, 3).map(function (p) { return p.name || ('+' + p.phone); }).join(', ')) + '.</li>');
if (unconfirmed.length) att.push('<li><b>' + unconfirmed.length + ' patient' + (unconfirmed.length > 1 ? 's haven’t' : ' hasn’t') + ' confirmed</b> today’s visit (' + esc(unconfirmed.slice(0, 3).map(function (r) { return r.name.split(' ')[0] + ' ' + r.time; }).join(', ')) + ').</li>');
if (reqOpen.length) att.push('<li><b>' + reqOpen.length + ' open request' + (reqOpen.length > 1 ? 's' : '') + '</b>: ' + esc(reqOpen.slice(0, 2).map(function (r) { return String(r.type || 'request') + ' (' + String(r.key || '') + ')'; }).join(', ')) + '.</li>');
if (unanswered.length) att.push('<li><b>' + unanswered.length + ' question' + (unanswered.length > 1 ? 's' : '') + ' Noor couldn’t answer</b>' + (unanswered[0].question || unanswered[0].text ? ': “' + esc(String(unanswered[0].question || unanswered[0].text).slice(0, 80)) + '”' : '') + '. Add the answer in the Knowledge tab.</li>');
if (!att.length) att.push('<li>Nothing urgent. Everything is handled.</li>');
const stat = function (a, b) { return '<div class="stat"><span>' + a + '</span><b>' + b + '</b></div>'; };
const pct = madeLastWeek.length ? Math.round(madeWeek.length / madeLastWeek.length * 100) : 0;
const css = '@page{size:A4;margin:0}*{box-sizing:border-box}body{margin:0;font-family:"DejaVu Sans","Liberation Sans",Arial,sans-serif;color:#0f2a2a;font-size:11px;-webkit-print-color-adjust:exact;print-color-adjust:exact}.head{background:linear-gradient(135deg,#0b5f58,#0f766e 50%,#14b8a6);color:#fff;padding:22px 30px 50px}.row{display:flex;justify-content:space-between;align-items:flex-start}.logo{display:flex;align-items:center;gap:10px;font-size:17px;font-weight:700}.logo i{width:32px;height:32px;border-radius:9px;background:#fff;color:#0f766e;display:flex;align-items:center;justify-content:center;font-style:normal;font-size:16px}.tag{font-size:10px;background:rgba(255,255,255,.18);border:1px solid rgba(255,255,255,.35);border-radius:99px;padding:3px 10px}h1{margin:16px 0 2px;font-size:24px}.sub{opacity:.9;font-size:12px}.body{padding:0 30px 24px}.kpis{display:flex;gap:10px;margin-top:-30px}.kpi{flex:1;background:#fff;border:1px solid #e3ecea;border-radius:12px;padding:12px 14px;box-shadow:0 6px 16px -12px rgba(15,42,42,.5)}.kpi b{display:block;font-size:21px;color:#0f766e}.kpi span{color:#5f7472;font-size:10.5px}.kpi em{font-style:normal;font-size:10px;color:#15803d;display:block;margin-top:2px}h2{font-size:13.5px;margin:20px 0 8px;padding-left:10px;border-left:4px solid #14b8a6}table{width:100%;border-collapse:collapse}th{text-align:left;font-size:9.5px;text-transform:uppercase;letter-spacing:.05em;color:#5f7472;padding:6px 8px;border-bottom:1.5px solid #e3ecea}td{padding:7px 8px;border-bottom:1px solid #eef3f2;vertical-align:top}tr:nth-child(even) td{background:#f8fbfa}td.empty{color:#5f7472;text-align:center;padding:16px}.time{font-weight:700;white-space:nowrap}.pill{display:inline-block;border-radius:99px;padding:2px 8px;font-size:9.5px;font-weight:700}.ok{background:#dcfce7;color:#15803d}.wait{background:#fef3c7;color:#b45309}.new{background:#e0f2fe;color:#0369a1}.fam{background:#f3e8ff;color:#7e22ce}.web{background:#e6f6f3;color:#0f766e}.grid2{display:flex;gap:14px}.grid2>div{flex:1}.box{border:1px solid #e3ecea;border-radius:12px;padding:12px 14px}.alert{border-color:#fcd34d;background:#fffbeb}.alert li{margin-bottom:5px}ul{margin:0;padding-left:16px}.stat{display:flex;justify-content:space-between;padding:5px 0;border-bottom:1px dashed #e3ecea}.stat:last-child{border:0}.stat b{color:#0f766e}.bar{height:8px;background:#e6f6f3;border-radius:99px;overflow:hidden;margin-top:3px}.bar i{display:block;height:100%;background:#14b8a6}.note{color:#5f7472;font-size:9.5px;margin:3px 0 6px}.foot{margin-top:16px;color:#7b8f8c;font-size:9.5px;display:flex;justify-content:space-between;border-top:1px solid #e3ecea;padding-top:8px}';
const html = '<!doctype html><html><head><meta charset="utf-8"><style>' + css + '</style></head><body>' +
  '<div class="head"><div class="row"><div class="logo"><i>' + esc(clinic.charAt(0)) + '</i>' + esc(clinic) + '</div><span class="tag">Daily report</span></div>' +
  '<h1>Good morning! Here is your day.</h1><div class="sub">' + now.toFormat('cccc d LLLL yyyy') + (c.address ? ' · ' + esc(c.address) : '') + ' · prepared ' + now.toFormat('h:mm a') + '</div></div>' +
  '<div class="body"><div class="kpis">' +
  '<div class="kpi"><b>' + rows.length + '</b><span>Appointments today</span><em>' + confirmedCount + ' confirmed by patients</em></div>' +
  '<div class="kpi"><b>' + money(todayValue) + '</b><span>Expected value today</span><em>from today’s bookings</em></div>' +
  '<div class="kpi"><b>' + madeYesterday.length + '</b><span>New bookings yesterday</span><em>' + webYesterday + ' from the website</em></div>' +
  '<div class="kpi"><b>' + newToday + '</b><span>New patients</span><em>first visit today</em></div></div>' +
  '<h2>Today’s schedule</h2><table><thead><tr><th>Time</th><th>Patient</th><th>Treatment</th><th>Dentist</th><th>Status</th></tr></thead><tbody>' + tableRows + '</tbody></table>' +
  '<div class="grid2"><div><h2>Needs your attention</h2><div class="box alert"><ul>' + att.join('') + '</ul></div></div>' +
  '<div><h2>Yesterday on WhatsApp</h2><div class="box">' + stat('Patients who messaged', Object.keys(people).length) + stat('Replies sent by Noor', outMsgs.length) + stat('Replied outside opening hours', afterHours) + stat('Voice notes answered', voice) + '</div></div></div>' +
  '<div class="grid2"><div><h2>Automatic messages sent yesterday</h2><div class="box">' + auto.map(function (a) { return stat(a[0], a[1]); }).join('') + '</div></div>' +
  '<div><h2>This week so far</h2><div class="box">' + stat('Bookings made by Noor', madeWeek.length) +
  (madeLastWeek.length ? '<div class="bar"><i style="width:' + Math.min(100, pct) + '%"></i></div><div class="note">' + pct + '% of last week’s ' + madeLastWeek.length + ' bookings</div>' : '') +
  stat('Estimated value', money(weekValue)) + stat('Leads still to convert', leads.length) + '</div></div></div>' +
  '<div class="foot"><span>Prepared automatically by Noor for ' + esc(clinic) + '</span><span>Questions? Reply to this WhatsApp message.</span></div></div></body></html>';
const fileName = clinic.replace(/[^A-Za-z0-9]+/g, '_') + '_Report_' + now.toFormat('yyyy-MM-dd') + '.pdf';
const summary = rows.length + ' appointments today (' + confirmedCount + ' confirmed), ' + madeYesterday.length + ' new bookings yesterday, ' + waiting.length + ' waiting for a person. Reply REPORT to get the full PDF.';
return [{ json: { html: html, fileName: fileName, owner: owner, caption: 'Good morning! Your ' + clinic + ' daily report for ' + now.toFormat('cccc d LLLL') + '.', date: now.toFormat('cccc d LLLL'), summary: summary } }];

const f = $('Build Daily PDF').first().json.fileName;
const out = [];
for (const item of $input.all()) { if (item.binary && item.binary.data) { item.binary.data.mimeType = 'application/pdf'; item.binary.data.fileName = f; item.binary.data.fileExtension = 'pdf'; } out.push(item); }
return out;

// Noor CEO Dashboard + CRM: live page built from the Sheet tabs, calendar and automatic-message log.
const Z = 'Asia/Dubai';
const now = DateTime.now().setZone(Z);
const today = now.startOf('day');
function all(n) { try { return $(n).all().map(function (i) { return i.json || {}; }).filter(function (r) { return Object.keys(r).length && !r.error; }); } catch (e) { return []; } }
function esc(s) { return String(s == null ? '' : s).replace(/[&<>"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; }); }
const q = (($('Dashboard Page').first() || {}).json || {}).query || {};
const pick = /^\d{4}-\d{2}-\d{2}$/.test(String(q.date || '')) ? DateTime.fromISO(String(q.date), { zone: Z }).startOf('day') : null;
const sel = pick && pick.isValid && pick <= today ? pick : null;
const days = sel ? 1 : ([1, 7, 30, 90].indexOf(Number(q.range)) >= 0 ? Number(q.range) : 30);
const from = sel ? sel : (days === 1 ? today : today.minus({ days: days - 1 }));
const end = sel ? sel.endOf('day') : now;
const dayShown = sel || today;
const c = {};
all('D Setup').filter(function (r) { return r.tab === 'clinic'; }).forEach(function (r) { c[r.name] = String(r.value || '').trim(); });
const prices = all('D Setup').filter(function (r) { return r.tab === 'price' && !isNaN(Number(r.value)); });
const clinic = c.clinic_name || 'BrightSmile Dental';
const cur = c.currency || 'AED';
const owner = String(c.owner_phone || '').replace(/\D/g, '');
const digits = function (p) { return String(p || '').replace(/\D/g, ''); };
const isTest = function (p) { const s = digits(p); return !s || /^000000000000/.test(s) || (owner && s === owner); };
const t = function (s) { const v = String(s || ''); let d = DateTime.fromFormat(v, 'yyyy-MM-dd HH:mm', { zone: Z }); if (!d.isValid) d = DateTime.fromISO(v, { zone: Z }); return d; };
const inRange = function (d) { return d.isValid && d >= from && d <= end; };
const valueOf = function (summary) { const s = String(summary || '').toLowerCase(); const p = prices.find(function (r) { return String(r.words || '').toLowerCase().split(',').map(function (w) { return w.trim(); }).filter(Boolean).some(function (w) { return s.includes(w); }); }); return p ? Number(p.value) : 0; };
const money = function (n) { return cur + ' ' + Math.round(n).toLocaleString('en-US'); };
const DAYS = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday'];
const openAt = function (d) { const h = String(c['hours_' + DAYS[d.weekday - 1]] || (d.weekday === 5 ? '14:00-21:00' : '09:00-21:00')); const m = h.match(/(\d{1,2}):(\d{2})\s*-\s*(\d{1,2}):(\d{2})/); if (!m) return false; const mins = d.hour * 60 + d.minute; return mins >= Number(m[1]) * 60 + Number(m[2]) && mins < Number(m[3]) * 60 + Number(m[4]); };

const patients = all('D Patients').filter(function (p) { return !isTest(p.phone); });
const convAll = all('D Conversations').filter(function (r) { return !isTest(r.phone); });
const conv = convAll.filter(function (r) { return inRange(t(r.time)); });
const inMsgs = conv.filter(function (r) { return r.direction === 'in'; });
const outMsgs = conv.filter(function (r) { return r.direction === 'out'; });
const eventsAll = all('D Events').filter(function (e) { return e.id && e.start && e.start.dateTime; });
const events = eventsAll.filter(function (e) { return e.status !== 'cancelled'; });
const evStart = function (e) { return DateTime.fromISO(e.start.dateTime, { zone: Z }); };
const evPhone = function (e) { const m = String(e.description || '').match(/phone:\s*\+?(\d{8,15})/i); return m ? m[1] : ''; };
const byNoor = function (e) { return /Booked by Noor/i.test(String(e.description || '')) && !/000000000000/.test(String(e.description || '')); };
const created = function (e) { return DateTime.fromISO(String(e.created || ''), { zone: Z }); };
const made = events.filter(function (e) { return byNoor(e) && inRange(created(e)); });
const web = made.filter(function (e) { return /online booking page/i.test(String(e.description || '')); });
const cancelled = eventsAll.filter(function (e) { return e.status === 'cancelled' && inRange(DateTime.fromISO(String(e.updated || ''), { zone: Z })); });
const revenue = made.reduce(function (s, e) { return s + valueOf(e.summary); }, 0);
const people = {}; inMsgs.forEach(function (r) { people[digits(r.phone)] = 1; });
const firstSeen = {}; convAll.forEach(function (r) { const p = digits(r.phone); if (r.direction === 'in' && p && !firstSeen[p]) firstSeen[p] = t(r.time); });
const newPeople = Object.keys(people).filter(function (p) { return firstSeen[p] && inRange(firstSeen[p]); });
const afterHours = outMsgs.filter(function (r) { const d = t(r.time); return d.isValid && !openAt(d); }).length;
const voice = inMsgs.filter(function (r) { return String(r.type || '') === 'audio'; }).length;
const sent = all('D Sent Log').filter(function (r) { return !isTest(r.phone) && inRange(t(r.sent_at)); });
const kind = function (k) { return sent.filter(function (r) { return k.indexOf(String(r.kind || '')) >= 0; }).length; };
const auto = [['Reminders', kind(['reminder', 'reminder3d', 'reminder_3d'])], ['Welcome & aftercare', kind(['tips', 'first_visit', 'aftercare'])], ['Follow-ups & win-back', kind(['followup', 'winback', 'win_back'])], ['Ratings & reviews', kind(['feedback', 'review'])], ['Recall & no-show', kind(['recall', 'missed'])], ['Slot offers', kind(['slot', 'slot_offer'])]];
const unanswered = all('D Unanswered').filter(function (r) { return !isTest(r.phone) && inRange(t(r.time)); });
const reqOpen = all('D Requests').filter(function (r) { return !isTest(r.phone) && ['ready', 'done', 'closed'].indexOf(String(r.status || '').toLowerCase().trim()) < 0; });

const labels = [], sMsgs = [], sBook = [];
const nDays = Math.max(days, sel ? 14 : 7);
for (let i = nDays - 1; i >= 0; i--) {
  const d0 = dayShown.minus({ days: i }), d1 = d0.plus({ days: 1 });
  labels.push(d0.toFormat('d LLL'));
  sMsgs.push(convAll.filter(function (r) { const d = t(r.time); return r.direction === 'in' && d.isValid && d >= d0 && d < d1; }).length);
  sBook.push(events.filter(function (e) { const d = created(e); return byNoor(e) && d.isValid && d >= d0 && d < d1; }).length);
}
const hours = new Array(24).fill(0);
inMsgs.forEach(function (r) { const d = t(r.time); if (d.isValid) hours[d.hour]++; });

const prof = {};
const P = function (ph) { const d = digits(ph); if (!d) return null; if (!prof[d]) prof[d] = { phone: d, name: '', status: '', last: null, msgs: 0, next: null, visits: 0, value: 0, tags: '' }; return prof[d]; };
patients.forEach(function (p) { const x = P(p.phone); if (!x) return; x.name = p.name || x.name; x.status = String(p.status || '').toLowerCase().trim(); x.tags = [p.new_or_returning, p.language].filter(Boolean).join(' · '); });
convAll.forEach(function (r) { const x = P(r.phone); if (!x) return; const d = t(r.time); if (r.direction === 'in') x.msgs++; if (d.isValid && (!x.last || d > x.last)) x.last = d; });
events.forEach(function (e) { const x = P(evPhone(e)); if (!x) return; const s = evStart(e); if (s >= now) { if (!x.next || s < x.next) x.next = s; } else { x.visits++; x.value += valueOf(e.summary); } if (!x.name) { const parts = String(e.summary || '').split(/\s+[–-]\s+/); x.name = parts.slice(1).join(' – '); } });
const stageOf = function (x) {
  if (/opted_out/.test(x.status)) return 'Opted out';
  if (x.status === 'human') return 'Needs a person';
  if (x.next) return 'Booked';
  if (x.visits) return x.last && x.last < now.minus({ days: 120 }) ? 'Inactive' : 'Patient';
  if (/no_show|missed/.test(x.status)) return 'No-show';
  if (x.status === 'lead' || x.msgs) return 'Lead';
  return 'New';
};
const list = Object.keys(prof).map(function (k) { const x = prof[k]; x.stage = stageOf(x); return x; }).sort(function (a, b) { return (b.last ? b.last.toMillis() : 0) - (a.last ? a.last.toMillis() : 0); });
const STAGES = ['Lead', 'Booked', 'Patient', 'Needs a person', 'No-show', 'Inactive', 'Opted out'];
const stageCount = {}; STAGES.forEach(function (s) { stageCount[s] = list.filter(function (x) { return x.stage === s; }).length; });
const conversion = (stageCount.Lead + stageCount.Booked + stageCount.Patient) ? Math.round((stageCount.Booked + stageCount.Patient) / (stageCount.Lead + stageCount.Booked + stageCount.Patient) * 100) : 0;

const todays = events.filter(function (e) { const s = evStart(e); return s >= dayShown && s < dayShown.plus({ days: 1 }) && !isTest(evPhone(e)); }).sort(function (a, b) { return evStart(a).toMillis() - evStart(b).toMillis(); });
const todayRows = todays.map(function (e) { const parts = String(e.summary || '').split(/\s+[–-]\s+/); const x = prof[evPhone(e)] || {}; const ok = /confirmed/i.test(String(x.status || '')); return '<tr><td><b>' + evStart(e).toFormat('HH:mm') + '</b></td><td>' + esc(parts.slice(1).join(' – ') || 'Patient') + '</td><td>' + esc(parts[0] || '') + '</td><td>' + (ok ? '<span class="pill ok">Confirmed</span>' : '<span class="pill wait">Not confirmed</span>') + '</td></tr>'; }).join('') || '<tr><td colspan="4" class="empty">No appointments on this day.</td></tr>';
const att = [];
const waiting = list.filter(function (x) { return x.stage === 'Needs a person'; });
if (waiting.length) att.push('<li><b>' + waiting.length + ' waiting for a person:</b> ' + esc(waiting.slice(0, 4).map(function (x) { return x.name || ('+' + x.phone); }).join(', ')) + '</li>');
if (reqOpen.length) att.push('<li><b>' + reqOpen.length + ' open requests</b> (reschedules, cancellations, callbacks)</li>');
if (unanswered.length) att.push('<li><b>' + unanswered.length + ' questions Noor could not answer.</b> Add answers in the Knowledge tab.</li>');
if (stageCount.Lead) att.push('<li><b>' + stageCount.Lead + ' leads</b> asked but have not booked yet. Noor is following up.</li>');
if (!att.length) att.push('<li>Nothing urgent. Everything is handled.</li>');

const crmRows = list.slice(0, 300).map(function (x) { return '<tr data-s="' + esc(x.stage) + '"><td>' + esc(x.name || '—') + '</td><td dir="ltr">+' + esc(x.phone) + '</td><td><span class="st st' + STAGES.indexOf(x.stage) + '">' + esc(x.stage) + '</span></td><td>' + (x.last ? x.last.toFormat('d LLL HH:mm') : '—') + '</td><td>' + (x.next ? x.next.toFormat('d LLL HH:mm') : '—') + '</td><td>' + x.visits + '</td><td>' + (x.value ? money(x.value) : '—') + '</td><td>' + esc(x.tags) + '</td></tr>'; }).join('') || '<tr><td colspan="8" class="empty">No patients yet.</td></tr>';
const kpi = function (v, l, s) { return '<div class="kpi"><b>' + v + '</b><span>' + l + '</span>' + (s ? '<em>' + s + '</em>' : '') + '</div>'; };
const rangeBtn = function (n, l) { return '<a class="rb' + (!sel && n === days ? ' on' : '') + '" href="?range=' + n + '">' + l + '</a>'; };
const prevD = dayShown.minus({ days: 1 }).toISODate(), nextD = dayShown.plus({ days: 1 });
const dayNav = '<a class="rb" href="?date=' + prevD + '">‹</a><input class="dp" type="date" max="' + today.toISODate() + '" value="' + (sel ? sel.toISODate() : '') + '" onchange="if(this.value)location.search=\'?date=\'+this.value">' + (sel && nextD <= today ? '<a class="rb" href="?date=' + nextD.toISODate() + '">›</a>' : '');
const title = sel ? sel.toFormat('cccc d LLLL yyyy') : (days === 1 ? 'Today' : 'Last ' + days + ' days');
const css = ':root{--b:#0f766e;--b2:#14b8a6;--soft:#e6f6f3;--ink:#0f2a2a;--mu:#5f7472;--li:#e3ecea;--bg:#f3f8f7}*{box-sizing:border-box}body{margin:0;font-family:"Plus Jakarta Sans",system-ui,Segoe UI,Arial,sans-serif;background:var(--bg);color:var(--ink)}.hd{background:linear-gradient(135deg,#0b5f58,var(--b) 50%,var(--b2));color:#fff;padding:20px 16px 64px}.in{max-width:1180px;margin:0 auto}.top{display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap}.lg{display:flex;gap:10px;align-items:center;font-weight:700;font-size:18px}.lg i{width:36px;height:36px;border-radius:10px;background:#fff;color:var(--b);display:grid;place-items:center;font-style:normal}.rg{display:flex;gap:6px;flex-wrap:wrap}.rb{color:#fff;text-decoration:none;border:1px solid rgba(255,255,255,.45);border-radius:99px;padding:6px 12px;font-size:13px}.rb.on{background:#fff;color:var(--b);font-weight:700}.dp{border:1px solid rgba(255,255,255,.45);background:rgba(255,255,255,.15);color:#fff;border-radius:99px;padding:5px 10px;font:inherit;font-size:13px;color-scheme:dark}h1{margin:16px 0 2px;font-size:clamp(22px,4vw,28px)}.sub{opacity:.9;font-size:14px}main{max-width:1180px;margin:-46px auto 0;padding:0 16px 30px}.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:12px}.kpi,.card{background:#fff;border:1px solid var(--li);border-radius:16px;box-shadow:0 8px 22px -18px rgba(15,42,42,.4)}.kpi{padding:14px 16px}.kpi b{display:block;font-size:24px;color:var(--b)}.kpi span{color:var(--mu);font-size:13px}.kpi em{display:block;font-style:normal;font-size:12px;color:#15803d;margin-top:2px}.grid{display:grid;grid-template-columns:2fr 1fr;gap:14px;margin-top:14px}@media(max-width:860px){.grid{grid-template-columns:1fr}}.card{padding:16px;min-width:0}h2{font-size:16px;margin:0 0 12px}table{width:100%;border-collapse:collapse;font-size:13.5px}th{text-align:left;font-size:11.5px;color:var(--mu);text-transform:uppercase;letter-spacing:.04em;padding:8px;border-bottom:1.5px solid var(--li)}td{padding:9px 8px;border-bottom:1px solid #eef3f2}.empty{color:var(--mu);text-align:center}.tw{overflow-x:auto}.pill{border-radius:99px;padding:2px 9px;font-size:12px;font-weight:700}.ok{background:#dcfce7;color:#15803d}.wait{background:#fef3c7;color:#b45309}ul{margin:0;padding-left:18px;line-height:1.7}.al{background:#fffbeb;border-color:#fcd34d}.row{display:flex;justify-content:space-between;padding:7px 0;border-bottom:1px dashed var(--li);font-size:14px}.row b{color:var(--b)}.pipe{display:grid;grid-template-columns:repeat(auto-fit,minmax(110px,1fr));gap:8px;margin-bottom:12px}.pp{border:1.5px solid var(--li);border-radius:12px;padding:10px;text-align:center;cursor:pointer;background:#fff;font:inherit}.pp b{display:block;font-size:20px}.pp.on{border-color:var(--b);background:var(--soft)}.st{border-radius:99px;padding:2px 9px;font-size:12px;font-weight:700;white-space:nowrap}.st0{background:#e0f2fe;color:#0369a1}.st1{background:#dcfce7;color:#15803d}.st2{background:var(--soft);color:var(--b)}.st3{background:#fee2e2;color:#b91c1c}.st4{background:#fef3c7;color:#b45309}.st5{background:#f1f5f9;color:#475569}.st6{background:#f3e8ff;color:#7e22ce}input.s{width:100%;padding:10px 12px;border:1.5px solid var(--li);border-radius:10px;font:inherit;margin-bottom:10px}canvas{max-height:260px}.ft{color:var(--mu);font-size:12px;text-align:center;margin-top:18px}';
