// Validates an inbox action: send a staff reply, pause Noor (take over) or resume Noor.
const b = (($('Inbox Action').first() || {}).json || {}).body || {};
const action = String(b.action || '').trim();
const phone = String(b.phone || '').replace(/\D/g, '');
const text = String(b.text || '').trim().slice(0, 4000);
let error = '';
if (['send', 'pause', 'resume'].indexOf(action) < 0) error = 'Unknown action';
else if (phone.length < 8 || phone.length > 15) error = 'Invalid phone number';
else if (action === 'send' && !text) error = 'Message is empty';
const time = DateTime.now().setZone('Asia/Dubai').toFormat('yyyy-MM-dd HH:mm');
return [{ json: { action: action, phone: phone, text: text, ok: !error, error: error, time: time, paused: action === 'resume' ? 'FALSE' : 'TRUE' } }];

// Noor Staff Inbox: all WhatsApp chats in one page. Staff can reply, pause Noor (take over) and hand back.
const Z = 'Asia/Dubai';
const now = DateTime.now().setZone(Z);
function all(n) { try { return $(n).all().map(function (i) { return i.json || {}; }).filter(function (r) { return Object.keys(r).length && !r.error; }); } catch (e) { return []; } }
const digits = function (p) { return String(p || '').replace(/\D/g, ''); };
const t = function (s) { const v = String(s || ''); let d = DateTime.fromFormat(v, 'yyyy-MM-dd HH:mm', { zone: Z }); if (!d.isValid) d = DateTime.fromISO(v, { zone: Z }); return d; };
const c = {};
all('I Setup').filter(function (r) { return r.tab === 'clinic'; }).forEach(function (r) { c[r.name] = String(r.value || '').trim(); });
const clinic = c.clinic_name || 'BrightSmile Dental';
const pats = {};
all('I Patients').forEach(function (p) { const d = digits(p.phone); if (d) pats[d] = p; });
const paused = {};
all('I Takeover').forEach(function (r) { const d = digits(r.phone); if (d) paused[d] = String(r.paused).trim().toUpperCase() === 'TRUE'; });
const th = {};
all('I Conversations').forEach(function (r) {
  const d = digits(r.phone); if (!d || /^000000000000/.test(d)) return;
  const tm = t(r.time);
  if (!th[d]) th[d] = { phone: d, msgs: [], last: null, lastIn: null };
  th[d].msgs.push({ d: r.direction === 'in' ? 'in' : (String(r.type || '') === 'staff' ? 'staff' : 'out'), k: String(r.type || ''), x: String(r.text || '').slice(0, 1500), t: tm.isValid ? tm.toFormat('d LLL HH:mm') : '' });
  if (tm.isValid && (!th[d].last || tm > th[d].last)) th[d].last = tm;
  if (r.direction === 'in' && tm.isValid) th[d].lastIn = tm;
});
const list = Object.keys(th).map(function (k) {
  const x = th[k], p = pats[k] || {};
  const st = String(p.status || '').toLowerCase().trim();
  return { phone: k, name: String(p.name || '').trim() || ('+' + k), status: st, needs: st === 'human', paused: !!paused[k], open24: !!(x.lastIn && x.lastIn > now.minus({ hours: 24 })), last: x.last ? x.last.toFormat('d LLL HH:mm') : '', ms: x.last ? x.last.toMillis() : 0, preview: (x.msgs[x.msgs.length - 1] || {}).x || '', msgs: x.msgs.slice(-80) };
}).sort(function (a, b) { return (b.needs - a.needs) || (b.paused - a.paused) || (b.ms - a.ms); }).slice(0, 150);
