// Validates a website chat message and prepares the input for Noor's brain.
const b = (($('Webchat Message').first() || {}).json || {}).body || {};
const phone = String(b.phone || '').replace(/\D/g, '');
const name = String(b.name || '').replace(/[<>\r\n]/g, ' ').trim().slice(0, 60);
const text = String(b.text || '').replace(/\r/g, '').trim().slice(0, 1000);
const ok = phone.length >= 8 && phone.length <= 15 && !!name && !!text;
return [{ json: { ok: ok, phone: phone, name: name, text: text, page: String(b.page || '').slice(0, 200), demo: String(b.demo || '') === 'glow' ? 'glow' : '', time: DateTime.now().setZone('Asia/Dubai').toFormat('yyyy-MM-dd HH:mm') } }];

// Finds the patient, checks if staff took over the chat, and builds the brain input.
const m = $('Check Chat').first().json;
const pats = $('M Patients').all().map(function (i) { return i.json || {}; });
const row = pats.filter(function (p) { return String(p.phone || '').replace(/\D/g, '') === m.phone; })[0];
