$('M Settings').all().forEach(function (i) { const r = i.json || {}; if (String(r.feature || '').trim() === 'web_chat' && String(r.enabled).trim().toUpperCase() === 'FALSE') on = false; });
const note = '[Website chat. The visitor typed their name "' + m.name + '" and this WhatsApp number themselves (not verified). Reply in short plain text, no WhatsApp buttons. Answer in the same language and dialect as the visitor\'s message after this note.] ';
// Demo chats keep their own history so a visitor who tried another demo never gets mixed answers.
