  h = h.replace(/Newsreader,\s*Georgia,\s*serif/g, '"Readex Pro",system-ui,sans-serif').replace(/"Instrument Sans"/g, '"Readex Pro"').replace(/"Plus Jakarta Sans"/g, '"Readex Pro"');
  const css = '<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Readex+Pro:wght@300;400;500;600&display=swap"><style id="hl-portal-v3">' +
    ':root{--hp-ink:#0F1E24;--hp-night:#0F2523;--hp-sea:#1B4D5C;--hp-gold:#C8932F;--hp-bg:#F2F4F7;--hp-line:#DDE3E8;--hp-mute:#5E6B73}' +
    'body{font-family:"Readex Pro",system-ui,sans-serif!important;background:var(--hp-bg)!important;color:var(--hp-ink)!important}' +
    '.hbar{background:var(--hp-night)!important;border-bottom:0!important;height:60px!important;box-shadow:0 6px 20px -12px rgba(0,0,0,.45)}' +
    '.hbar .wm{color:#fff!important;font-family:"Readex Pro",sans-serif!important;font-weight:500!important;font-size:20px!important}.hbar .wm span{color:var(--hp-gold)!important}' +
    '.hbar .wm:after{content:"Portal";margin-left:9px;padding:2px 8px;font-size:11px;font-weight:500;letter-spacing:.08em;text-transform:uppercase;color:var(--hp-night);background:var(--hp-gold);border-radius:20px;vertical-align:3px}' +
    '.hbar nav a{color:rgba(255,255,255,.66)!important;padding:19px 13px!important;transition:color .2s}.hbar nav a:hover{color:#fff!important}.hbar nav a.on{color:#fff!important;border-bottom-color:var(--hp-gold)!important}' +
    '.hbar .me{color:rgba(255,255,255,.6)!important}.hbar .me a{color:#fff!important}' +
    'h1,h2,h3,.hd h1,.card h2{font-family:"Readex Pro",sans-serif!important;letter-spacing:-.01em!important}.hd h1{font-weight:500!important}' +
    '.card,.kpi,.k,.it,.box{border-radius:12px!important;border:1px solid var(--hp-line)!important;box-shadow:0 1px 2px rgba(15,30,36,.04),0 8px 24px -18px rgba(15,30,36,.25)!important;animation:hpIn .45s cubic-bezier(.2,.7,.2,1) both}' +
    '.kpi b,.k b{font-family:"Readex Pro",sans-serif!important;font-weight:600!important;color:var(--hp-sea)}' +
