  return h.indexOf('</head>') >= 0 ? h.replace('</head>', css + '</head>') : css + h;
}

// Halora intro calls: works out which days to read from Ziad's Google Calendar.
// GET ?days=14 -> availability for the next 14 days (one request for the whole picker). POST -> the chosen day only.
let mode = 'slots', wh = {};
try { if ($('Call Book').isExecuted) { mode = 'book'; wh = $('Call Book').first().json || {}; } } catch (e) { mode = 'slots'; }
if (mode === 'slots') { try { wh = $('Call Slots').first().json || {}; } catch (e) { wh = {}; } }
let b = wh.body || {}; if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
const q = wh.query || {};
const Z = 'Asia/Dubai';
const now = DateTime.now().setZone(Z);
let d = DateTime.fromISO(String(mode === 'book' ? (b.date || '') : (q.date || '')), { zone: Z });
if (!d.isValid || d < now.startOf('day')) d = now;
const days = mode === 'book' ? 1 : Math.min(21, Math.max(1, Number(q.days) || 14));
const start = d.startOf('day');
return [{ json: { mode: mode, body: b, query: q, date: start.toFormat('yyyy-MM-dd'), days: days, timeMin: start.toISO(), timeMax: start.plus({ days: days }).toISO() } }];

// Halora intro calls: free 20-minute slots from Ziad's Google Calendar, and checks a booking before it is created.
// Hours: Sunday to Thursday, 10:00-18:00 Dubai time, a slot every 30 minutes (10 minutes buffer), at least 4 hours notice.
const Z = 'Asia/Dubai', OPEN = 10, CLOSE = 18, LEN = 20, STEP = 30, BUFFER = 10, NOTICE_H = 4;
const WORK = [7, 1, 2, 3, 4]; // Luxon weekdays: 7 = Sunday ... 4 = Thursday
const r = $('Call Range').first().json;
const now = DateTime.now().setZone(Z);
const busy = $('Call Calendar').all().map(function (i) { return i.json || {}; })
  .filter(function (e) { return e && e.start && e.start.dateTime && e.status !== 'cancelled' && e.transparency !== 'transparent'; })
  .map(function (e) { return [DateTime.fromISO(e.start.dateTime, { zone: Z }).minus({ minutes: BUFFER }), DateTime.fromISO((e.end && e.end.dateTime) || e.start.dateTime, { zone: Z }).plus({ minutes: BUFFER })]; });
const isFree = function (s) { const e = s.plus({ minutes: LEN }); return !busy.some(function (b) { return s < b[1] && b[0] < e; }); };
function slotsFor(day) {
  if (WORK.indexOf(day.weekday) < 0) return [];
  const out = [];
  for (let s = day.set({ hour: OPEN, minute: 0, second: 0, millisecond: 0 }); s.plus({ minutes: LEN }) <= day.set({ hour: CLOSE, minute: 0 }); s = s.plus({ minutes: STEP })) {
    if (s < now.plus({ hours: NOTICE_H })) continue;
    if (isFree(s)) out.push(s.toFormat('HH:mm'));
  }
  return out;
}
const first = DateTime.fromISO(r.date, { zone: Z });
let owner = '';
try { $('Call Setup').all().forEach(function (i) { const x = i.json || {}; if (x.tab === 'clinic' && x.name === 'owner_phone') owner = String(x.value || '').replace(/\D/g, ''); }); } catch (e) { owner = ''; }

if (r.mode === 'slots') {
  const days = [];
  for (let i = 0; i < r.days; i++) { const day = first.plus({ days: i }); days.push({ date: day.toFormat('yyyy-MM-dd'), slots: slotsFor(day) }); }
  return [{ json: { route: 'slots', body: { ok: true, timezone: 'Dubai (GMT+4)', minutes: LEN, days: days } } }];
}

const b = r.body || {};
const ar = String(b.language || '') === 'ar';
const bad = function (en, a) { return [{ json: { route: 'error', body: { ok: false, error: ar ? a : en } } }]; };
const clean = function (v, n) { return String(v || '').replace(/[<>\r\n]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, n); };
if (String(b.website || '').trim()) return bad('Something went wrong.', 'حدث خطأ.');
const name = clean(b.name, 80), clinic = clean(b.clinic, 120), email = clean(b.email, 120).toLowerCase(), note = clean(b.note, 400);
let phone = String(b.phone || '').replace(/\D/g, ''); if (phone.startsWith('00')) phone = phone.slice(2); if (/^0?5\d{8}$/.test(phone)) phone = '971' + phone.replace(/^0/, '');
if (name.length < 2) return bad('Please enter your name.', 'يرجى كتابة اسمك.');
if (clinic.length < 2) return bad('Please enter your clinic name.', 'يرجى كتابة اسم العيادة.');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) return bad('Please check your email address.', 'يرجى مراجعة البريد الإلكتروني.');
if (phone.length < 8 || phone.length > 15) return bad('Please enter your WhatsApp number with the country code.', 'يرجى كتابة رقم الواتساب مع رمز الدولة.');
const time = String(b.time || '');
if (!/^\d{2}:\d{2}$/.test(time) || slotsFor(first).indexOf(time) < 0) return bad('That time was just taken. Please pick another one.', 'هذا الوقت لم يعد متاحاً. اختر وقتاً آخر.');
const s = DateTime.fromFormat(r.date + ' ' + time, 'yyyy-MM-dd HH:mm', { zone: Z });
const e = s.plus({ minutes: LEN });
const when = s.toFormat('cccc d LLLL') + ' at ' + s.toFormat('HH:mm') + ' Dubai time';
return [{ json: {
  route: 'book', start: s.toISO(), end: e.toISO(), email: email, owner: owner,
  summary: 'Halora intro call · ' + clinic,
  description: 'Name: ' + name + '\nClinic: ' + clinic + '\nEmail: ' + email + '\nWhatsApp: +' + phone + (note ? '\nNote: ' + note : '') + '\n\nBooked from askhalora.com',
  alert: 'New Halora intro call booked\n' + name + ' · ' + clinic + '\n' + when + '\nWhatsApp: +' + phone + '\nEmail: ' + email + (note ? '\nNote: ' + note : ''),
  when: when, name: name, ar: ar
} }];

// Applies the Halora Portal brand to pages built in Check Session (sign in, setup, team access).
const it = Object.assign({}, $input.first().json);
Object.keys(it).forEach(function (k) { if (typeof it[k] === 'string' && it[k].indexOf('</head>') >= 0) it[k] = portalBrand(it[k]); });
return [{ json: it }];

function portalBrand(h) {
  if (!h || h.indexOf('hl-portal-v3') >= 0) return h;
  const M = [['#1f3b2d','#1B4D5C'],['#3d6650','#2F6F80'],['#16301f','#123A46'],['#ebefe6','#E6EEF2'],['#f5f1e8','#F2F4F7'],['#e2dccf','#DDE3E8'],
    ['#1c1b18','#0F1E24'],['#6e675c','#5E6B73'],['#efe9dd','#EBEFF3'],['#e4eadf','#E3ECF0'],['#f1ece2','#EEF2F5'],['#fbf8f1','#F8FAFB'],['#fffdf8','#FFFFFF'],['#b4572e','#C8932F'],
    ['#0f766e','#1B4D5C'],['#14b8a6','#2F6F80'],['#f3f8f7','#F2F4F7'],['#0f2a2a','#0F1E24']];
  M.forEach(function (m) { h = h.split(m[0]).join(m[1]).split(m[0].toUpperCase()).join(m[1]); });
  h = h.replace(/Newsreader,\s*Georgia,\s*serif/g, '"Readex Pro",system-ui,sans-serif').replace(/Newsreader,serif/g, '"Readex Pro",sans-serif').replace(/"Instrument Sans"/g, '"Readex Pro"').replace(/"Plus Jakarta Sans"/g, '"Readex Pro"');
  const css = '<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Readex+Pro:wght@300;400;500;600&display=swap"><style id="hl-portal-v3">' +
    ':root{--hp-ink:#0F1E24;--hp-night:#0F2523;--hp-sea:#1B4D5C;--hp-gold:#C8932F;--hp-bg:#F2F4F7;--hp-line:#DDE3E8;--hp-mute:#5E6B73}' +
    'body{font-family:"Readex Pro",system-ui,sans-serif!important;color:var(--hp-ink)}h1,h2,h3{font-family:"Readex Pro",sans-serif!important;font-weight:500!important;letter-spacing:-.01em!important}' +
    'button,input,select,textarea,.btn{border-radius:8px!important;font-family:"Readex Pro",sans-serif!important}' +
    'button[type=submit],.btn,.go{background:var(--hp-sea)!important;border-color:var(--hp-sea)!important;color:#fff!important}' +
    'input:focus,select:focus,textarea:focus{outline:2px solid var(--hp-gold)!important;outline-offset:0}' +
    '.hbar{background:var(--hp-night)!important;border-bottom:0!important}.hbar .wm{color:#fff!important;font-family:"Readex Pro",sans-serif!important}.hbar .wm span{color:var(--hp-gold)!important}' +
    '.hbar nav a{color:rgba(255,255,255,.66)!important}.hbar nav a.on{color:#fff!important;border-bottom-color:var(--hp-gold)!important}.hbar .me,.hbar .me a{color:rgba(255,255,255,.75)!important}' +
    '</style>';
  return h.indexOf('</head>') >= 0 ? h.replace('</head>', css + '</head>') : css + h;
}

// Website demo chats are not kept: every night, collect the visitor IDs used in website demo chats so their chat history is deleted.
// Switch: set CLEANUP_ON to false to keep demo chats.
const CLEANUP_ON = true;
if (!CLEANUP_ON) return [];
const seen = {};
$input.all().forEach(function (i) { const p = String((i.json || {}).phone || '').trim(); if (p) seen[p] = 1; });
return Object.keys(seen).map(function (p) { return { json: { phone: p } }; });

// Intro calls: details for the WhatsApp confirmation and reminder sent to the person who booked. Switch: set WA_ON to false to stop these messages.
const WA_ON = true;
if (!WA_ON) return [];
const b = ($('Call Range').first().json.body) || {};
const lg = $('Call Logic').first().json;
const ev = $('Create Call Event').first().json || {};
let phone = String(b.phone || '').replace(/\D/g, '');
if (phone.startsWith('00')) phone = phone.slice(2);
if (/^0?5\d{8}$/.test(phone)) phone = '971' + phone.replace(/^0/, '');
if (phone.length < 8) return [];
const ar = String(b.language || '') === 'ar';
const s = DateTime.fromISO(lg.start, { zone: 'Asia/Dubai' });
const meet = ev.hangoutLink || 'link in your email invite';
const remind = s.minus({ hours: 1 });
return [{ json: {
  phone: phone,
  lang: ar ? 'ar' : 'en',
  name: String(lg.name || b.name || '').split(' ')[0] || (ar ? 'أهلاً' : 'there'),
  service: (ar ? 'مكالمة تعريفية مع هالورا (Google Meet: ' : 'Halora intro call (Google Meet: ') + meet + ')',
  date: s.setLocale(ar ? 'ar' : 'en').toFormat('cccc d LLLL'),
  time: s.toFormat('HH:mm') + (ar ? ' بتوقيت دبي' : ' Dubai time'),
  remindAt: remind.toISO(),
  remindLater: remind > DateTime.now().plus({ minutes: 5 })
} }];

// Website voice note: keeps the audio file as binary 'data' and checks the visitor details.
const it = $input.first();
const b = (it.json && it.json.body) || {};
const bin = it.binary || {};
const k = Object.keys(bin)[0];
const phone = String(b.phone || '').replace(/\D/g, '');
const name = String(b.name || '').replace(/[<>\r\n]/g, ' ').trim().slice(0, 60);
const ok = !!k && phone.length >= 8 && phone.length <= 15 && !!name;
return [{ json: { ok: ok, phone: phone, name: name, page: String(b.page || '').slice(0, 200), lang: String(b.lang || '') === 'ar' ? 'ar' : 'en' }, binary: k ? { data: bin[k] } : {} }];

// Turns the transcript into a normal web chat message for Noor.
const p = $('Voice Prep').first().json;
const t = String((($input.first() || {}).json || {}).text || '').trim();
const heard = !!p.ok && t.replace(/[^\p{L}\p{N}]/gu, '').length >= 2;
return [{ json: { phone: p.phone, name: p.name, page: p.page, lang: p.lang, transcript: t, heard: heard, text: '[Voice note from the patient, transcribed word for word. Answer exactly what they asked, every question in order, in the language they spoke. If a word looks slightly misheard, use the clinic meaning that fits.] Transcript: ' + t } }];
